mapper.select:
select r.id, r.articleId, r.messageId, r.reporterId, r.type, r.reason, r.status, r.handleResult, r.createTime, r.updateTime, a.title as articleTitle, m.content as messageContent, u.nickname as reporterName from t_report r left join t_article a on r.articleId = a.id left join t_message m on r.messageId = m.id left join t_user u on r.reporterId = u.id
and r.status = #{status,jdbcType=TINYINT}
order by r.status asc, r.createTime desc limit #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}

select count(1)
from t_report r


    and r.status = #{status,jdbcType=TINYINT}

mapper.update:
update t_report
set status = #{status,jdbcType=TINYINT},
  handleResult = #{handleResult,jdbcType=VARCHAR},
  updateTime = #{updateTime,jdbcType=TIMESTAMP}
where id = #{id,jdbcType=BIGINT}

